}

type daemonConn struct {
	userID         string
	deviceID       string
	deviceName     string
	agent          string
	agentLabel     string
	agents         []protocol.AgentCapability
	workspaces     []protocol.Workspace
	conn           *websocket.Conn
	send           chan protocol.Envelope
	done           chan struct{}
	closeOnce      sync.Once
	closed         atomic.Bool
	mu             sync.Mutex
	terminalBinary bool
	directEndpoint *protocol.DirectEndpoint
	lastSeen       atomic.Int64
}

func (dc *daemonConn) markSeen(now time.Time) {
	if dc != nil {
		dc.lastSeen.Store(now.Unix())
	}
}

func (dc *daemonConn) lastSeenUnix() int64 {
	if dc == nil {
		return 0
	}
	return dc.lastSeen.Load()
}

func (dc *daemonConn) enqueue(env protocol.Envelope) bool {
	if dc == nil || dc.send == nil || dc.closed.Load() {
		return false
	}
	if dc.done == nil {
		dc.send <- env
		return !dc.closed.Load()
	}
	select {
	case dc.send <- env:
		return !dc.closed.Load()
	case <-dc.done:
		return false
	}
}

func (dc *daemonConn) shutdown() {
	dc.closeOnce.Do(func() {
		dc.closed.Store(true)
		if dc.done != nil {
			close(dc.done)
		}
		if dc.conn != nil {
			_ = dc.conn.Close()
		}
	})
}

func (dc *daemonConn) writeEnvelopeDirect(env protocol.Envelope) bool {
	if dc == nil || dc.conn == nil || dc.closed.Load() {
		return false
	}
	dc.mu.Lock()
	if dc.closed.Load() {
		dc.mu.Unlock()
		return false
	}
	err := writeEnvelopeWithin(dc.conn, env, webSocketWriteTimeout)
	dc.mu.Unlock()
	if err != nil {
		dc.shutdown()
		return false
	}
	return true
}

func (dc *daemonConn) writeMessageDirect(messageType int, data []byte) bool {
	if dc == nil || dc.conn == nil || dc.closed.Load() {
		return false
	}
	dc.mu.Lock()
	if dc.closed.Load() {
		dc.mu.Unlock()
		return false
	}
	err := writeWebSocketMessageWithin(dc.conn, messageType, data, webSocketWriteTimeout)
	dc.mu.Unlock()
	if err != nil {
		dc.shutdown()
		return false
	}
	return true
}

type webConn struct {
	userID    string
	conn      *websocket.Conn
	send      chan protocol.Envelope
	done      chan struct{}
	closeOnce sync.Once
	closed    atomic.Bool
}

type terminalConn struct {
	conn     *websocket.Conn
	clientID string
	mu       sync.Mutex
}

type agentChatConn struct {
	userID        string
	taskID        string
	projectID     string
	historyPaging bool
	conn          *websocket.Conn
	send          chan protocol.Envelope
	done          chan struct{}
	closeOnce     sync.Once
	closed        atomic.Bool
}

func enqueueClientEnvelope(send chan protocol.Envelope, done <-chan struct{}, closed *atomic.Bool, env protocol.Envelope, wait bool) bool {
	if send == nil || closed.Load() {
		return false
	}
	if done == nil {
		if wait {
			send <- env
			return !closed.Load()
		}
		select {
		case send <- env:
			return !closed.Load()
		default:
			return false
		}
	}
	if wait {
		select {
		case send <- env:
			return !closed.Load()
		case <-done:
			return false
		}
	}
	select {
	case send <- env:
		return !closed.Load()
	case <-done:
		return false
	default:
		return false
	}
}

func (wc *webConn) enqueue(env protocol.Envelope) bool {
	if wc == nil {
		return false
	}
	return enqueueClientEnvelope(wc.send, wc.done, &wc.closed, env, true)
}

func (wc *webConn) tryEnqueue(env protocol.Envelope) bool {
	if wc == nil {
		return false
	}
	return enqueueClientEnvelope(wc.send, wc.done, &wc.closed, env, false)
}

func (wc *webConn) shutdown() {
	if wc == nil {
		return
	}
	wc.closeOnce.Do(func() {
		wc.closed.Store(true)
		if wc.done != nil {
			close(wc.done)
		}
		if wc.conn != nil {
			_ = wc.conn.Close()
		}
	})
}

func (ac *agentChatConn) enqueue(env protocol.Envelope) bool {
	if ac == nil {
		return false
	}
	return enqueueClientEnvelope(ac.send, ac.done, &ac.closed, env, true)
}

func (ac *agentChatConn) tryEnqueue(env protocol.Envelope) bool {
	if ac == nil {
		return false
	}
	return enqueueClientEnvelope(ac.send, ac.done, &ac.closed, env, false)
}

func (ac *agentChatConn) shutdown() {
	if ac == nil {
		return
	}
	ac.closeOnce.Do(func() {
		ac.closed.Store(true)
		if ac.done != nil {
			close(ac.done)
		}
		if ac.conn != nil {
			_ = ac.conn.Close()
		}
	})
}

