	if h.agentChatConns[key] == nil {
		h.agentChatConns[key] = make(map[*agentChatConn]struct{})
	}
	h.agentChatConns[key][ac] = struct{}{}
	h.mu.Unlock()

	go func() {
		writeLoop(conn, ac.send, ac.done)
		ac.shutdown()
	}()
